
import { useState } from "react";

function InvestigationRoom() {
  // Get the mystery generated by Gemini
  const savedMystery = sessionStorage.getItem("generatedMystery");
  const mystery = savedMystery ? JSON.parse(savedMystery) : null;

  const [discoveredClues, setDiscoveredClues] = useState([]);
  const [hintsUsed, setHintsUsed] = useState(0);
  const [selectedHints, setSelectedHints] = useState([]);

  const [loadingClue, setLoadingClue] = useState("");
  const [loadingHint, setLoadingHint] = useState(false);
  const [error, setError] = useState("");

  const API_URL = "http://localhost:5000";

  if (!mystery) {
    return (
      <div className="min-h-screen bg-[#080b14] p-8 text-center text-white">
        <h1 className="text-2xl font-bold">No Mystery Found</h1>

        <p className="mt-3 text-gray-400">
          Please generate a new mystery first.
        </p>

        <button
          onClick={() => (window.location.href = "/create")}
          className="mt-6 rounded-xl bg-purple-600 px-6 py-3"
        >
          Create Mystery
        </button>
      </div>
    );
  }

  // Discover a clue through the backend
  async function discoverClue(clue) {
    if (discoveredClues.includes(clue.id) || loadingClue) {
      return;
    }

    setLoadingClue(clue.id);
    setError("");

    try {
      const response = await fetch(
        `${API_URL}/api/mysteries/${mystery.caseId}/clues/${clue.id}/discover`,
        {
          method: "POST",
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Could not discover clue.");
      }

      setDiscoveredClues((previous) => [...previous, clue.id]);
    } catch (err) {
      console.error("Clue discovery error:", err);
      setError(err.message || "Could not discover clue.");
    } finally {
      setLoadingClue("");
    }
  }

  // Request a hint through the backend
  async function requestHint() {
    if (
      hintsUsed >= mystery.hintsAvailable ||
      loadingHint
    ) {
      return;
    }

    setLoadingHint(true);
    setError("");

    try {
      const response = await fetch(
        `${API_URL}/api/mysteries/${mystery.caseId}/hints`,
        {
          method: "POST",
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Could not get a hint.");
      }

      setSelectedHints((previous) => [...previous, data.hint]);
      setHintsUsed(data.hintsUsed);
    } catch (err) {
      console.error("Hint request error:", err);
      setError(err.message || "Could not get a hint.");
    } finally {
      setLoadingHint(false);
    }
  }

  return (
    <div className="min-h-screen bg-[#080b14] px-6 py-8 text-white">
      <div className="mx-auto max-w-6xl">

        <button
          onClick={() => (window.location.href = "/create")}
          className="mb-8 text-gray-400 hover:text-white"
        >
          ← Back
        </button>

        {/* Case Details */}
        <div className="rounded-2xl border border-purple-400/20 bg-purple-500/10 p-8">
          <p className="text-sm uppercase tracking-[0.3em] text-purple-300">
            Case File #{mystery.caseId?.slice(0, 8) || "001"}
          </p>

          <h1 className="mt-3 text-3xl font-extrabold md:text-4xl">
            {mystery.title}
          </h1>

          <p className="mt-4 leading-7 text-gray-300">
            {mystery.description}
          </p>

          <div className="mt-6 flex flex-wrap gap-3 text-sm">
            <span className="rounded-full bg-white/10 px-4 py-2">
              Difficulty: {mystery.difficulty}
            </span>

            <span className="rounded-full bg-white/10 px-4 py-2">
              Clues: {discoveredClues.length}/{mystery.clues.length}
            </span>

            <span className="rounded-full bg-white/10 px-4 py-2">
              Hints used: {hintsUsed}/{mystery.hintsAvailable}
            </span>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="mt-6 rounded-xl border border-red-400/30 bg-red-500/10 p-4 text-red-300">
            {error}
          </div>
        )}

        {/* Suspects */}
        <section className="mt-12">
          <h2 className="text-2xl font-bold">Suspects</h2>

          <p className="mt-2 text-gray-400">
            Read their statements and look for contradictions.
          </p>

          <div className="mt-6 grid gap-5 md:grid-cols-3">
            {mystery.suspects.map((suspect, index) => (
              <div
                key={suspect.name}
                className="rounded-2xl border border-white/10 bg-white/[0.03] p-6"
              >
                <div className="text-4xl">
                  {["👩", "🕴️", "🧑‍💼", "🕵️", "👨‍💼"][index % 5]}
                </div>

                <h3 className="mt-4 text-lg font-bold">
                  {suspect.name}
                </h3>

                <p className="mt-1 text-sm text-purple-300">
                  {suspect.role}
                </p>

                <p className="mt-4 leading-6 text-gray-400">
                  {suspect.statement}
                </p>
              </div>
            ))}
          </div>
        </section>

        {/* Evidence Board */}
        <section className="mt-12">
          <h2 className="text-2xl font-bold">Evidence Board</h2>

          <p className="mt-2 text-gray-400">
            Investigate each clue to uncover important evidence.
          </p>

          <div className="mt-6 grid gap-4 md:grid-cols-2">
            {mystery.clues.map((clue, index) => {
              const discovered = discoveredClues.includes(clue.id);
              const loading = loadingClue === clue.id;

              return (
                <div
                  key={clue.id}
                  className="rounded-xl border border-white/10 bg-white/[0.03] p-5"
                >
                  <p className="font-semibold">
                    Evidence {index + 1}
                  </p>

                  <p className="mt-2 text-sm text-gray-300">
                    {discovered
                      ? clue.description
                      : "Undiscovered evidence"}
                  </p>

                  {discovered && (
                    <div className="mt-4 rounded-lg border border-purple-400/20 bg-purple-500/10 p-4">
                      <p className="text-xs font-bold uppercase tracking-wider text-purple-300">
                        What this reveals
                      </p>

                      <p className="mt-2 text-sm leading-6 text-gray-300">
                        {clue.revelation}
                      </p>
                    </div>
                  )}

                  <button
                    onClick={() => discoverClue(clue)}
                    disabled={discovered || loadingClue !== ""}
                    className="mt-4 rounded-lg bg-purple-600 px-4 py-2 text-sm font-semibold transition hover:bg-purple-500 disabled:bg-gray-700"
                  >
                    {loading
                      ? "Investigating..."
                      : discovered
                      ? "Discovered ✓"
                      : "Investigate"}
                  </button>
                </div>
              );
            })}
          </div>
        </section>

        {/* Hints */}
        <section className="mt-12 rounded-2xl border border-white/10 bg-white/[0.03] p-6">
          <h2 className="text-xl font-bold">Need a Hint?</h2>

          <p className="mt-2 text-gray-400">
            Use hints to help you solve the mystery.
          </p>

          {selectedHints.map((hint, index) => (
            <div
              key={index}
              className="mt-5 rounded-xl border border-yellow-400/20 bg-yellow-500/10 p-4"
            >
              <p className="text-sm font-semibold text-yellow-300">
                Hint {index + 1}
              </p>

              <p className="mt-2 text-gray-200">
                {hint}
              </p>
            </div>
          ))}

          <button
            onClick={requestHint}
            disabled={
              hintsUsed >= mystery.hintsAvailable || loadingHint
            }
            className="mt-5 rounded-lg border border-purple-400/40 px-5 py-3 font-semibold text-purple-300 transition hover:bg-purple-500/10 disabled:opacity-50"
          >
            {loadingHint
              ? "Getting Hint..."
              : `Request Hint (${mystery.hintsAvailable - hintsUsed} remaining)`}
          </button>
        </section>

        {/* Accusation */}
        <section className="mt-12 rounded-2xl border border-purple-400/30 bg-purple-500/10 p-6 text-center">
          <h2 className="text-xl font-bold">
            Ready to Solve the Case?
          </h2>

          <p className="mt-3 text-gray-400">
            Review the evidence and decide who you believe is responsible.
          </p>

          <button
            onClick={() => (window.location.href = "/accusation")}
            className="mt-6 rounded-xl bg-purple-600 px-8 py-4 font-semibold transition hover:bg-purple-500"
          >
            Make Your Accusation →
          </button>
        </section>

      </div>
    </div>
  );
}

export default InvestigationRoom;
